/* 职责：玩家的游戏 · 视觉层（CSS + 横幅资源变量）。
   配色跟随 CE 现有主题 token（黑金为默认，其他主题自动继承 --mce-accent）。
   横幅/分组图标：MB_CE_PG_ART 与 MB_CE_PG_ICONS 均为 data URI；为空时用 CSS 渐变/字形兜底，不依赖外部文件。 */
	var MB_CE_PG_ART = "data:image/jpeg;base64,";
	var MB_CE_PG_ICONS = "data:image/png;base64,";
	MB_CSS += "" +
		".mce-pg-hero{position:relative;display:flex;align-items:center;gap:14px;min-height:132px;padding:14px 16px;margin:2px 0 10px;border:1px solid var(--mce-border);border-radius:calc(var(--mce-radius) + 4px);overflow:hidden;background:" +
		"linear-gradient(115deg,rgba(8,8,10,.94) 0%,rgba(26,20,8,.86) 46%,rgba(8,8,10,.96) 100%)," +
		"radial-gradient(circle at 82% 18%,rgba(212,175,55,.28),transparent 44%)," +
		"repeating-linear-gradient(90deg,rgba(255,255,255,.035) 0 1px,transparent 1px 7px);background-size:cover;background-position:center}" +
		".mce-pg-hero:after{content:'';position:absolute;inset:auto 0 0 0;height:2px;background:linear-gradient(90deg,transparent,var(--mce-accent),transparent);opacity:.75}" +
		".mce-pg-hero-mark{flex:none;width:64px;height:64px;display:flex;align-items:center;justify-content:center;border:1px solid var(--mce-accent);border-radius:10px;color:var(--mce-accent);font-size:32px;font-weight:900;background:rgba(0,0,0,.36);box-shadow:0 0 24px -8px var(--mce-accent),inset 0 0 18px -10px var(--mce-accent);transform:rotate(-3deg)}" +
		".mce-pg-hero-text{min-width:0;flex:1}" +
		".mce-pg-kicker{font-size:10px;letter-spacing:.3em;color:var(--mce-accent);opacity:.8;font-weight:700}" +
		".mce-pg-title{font-size:22px;line-height:1.2;font-weight:900;color:var(--mce-txt-strong);letter-spacing:.04em;text-shadow:0 0 18px rgba(212,175,55,.22)}" +
		".mce-pg-sub{font-size:12px;line-height:1.55;color:var(--mce-txt);opacity:.86;margin-top:3px}" +
		".mce-pg-badges{display:flex;flex-wrap:wrap;gap:6px;margin-top:7px}" +
		".mce-pg-badge{font-size:10px;line-height:1;padding:4px 7px;border:1px solid var(--mce-border);border-radius:999px;color:var(--mce-txt-strong);background:rgba(0,0,0,.28);white-space:nowrap}" +
		".mce-pg-toolbar{display:flex;flex-wrap:wrap;gap:7px;align-items:center;margin:2px 0 7px}" +
		".mce-pg-actions,.mce-pg-mode,.mce-pg-presets{display:flex;flex-wrap:wrap;gap:6px;align-items:center}" +
		".mce-pg-search{flex:1 1 220px;min-width:170px;margin:0}" +
		".mce-pg-presets{padding:6px 8px;margin:0 0 8px;border:1px dashed var(--mce-border);border-radius:var(--mce-radius);background:rgba(0,0,0,.14)}" +
		".mce-pg-pre-label{font-size:11px;color:var(--mce-accent);font-weight:700;margin-right:2px}" +
		".mce-pg-count{font-size:11px;text-align:right;color:var(--mce-accent);opacity:.9;padding:2px 2px 0}" +
		".mce-pg-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(238px,1fr));gap:8px;margin:6px 0 4px}" +
		".mce-pg-card{border:1px solid var(--mce-border);border-radius:var(--mce-radius);background:linear-gradient(160deg,var(--mce-bg-btn),rgba(0,0,0,.16));padding:8px;min-width:0;transition:border-color .16s ease,box-shadow .16s ease,transform .12s ease}" +
		".mce-pg-card.on{border-color:var(--mce-accent);box-shadow:0 0 0 1px rgba(212,175,55,.18),0 0 20px -12px var(--mce-accent);background:linear-gradient(160deg,rgba(212,175,55,.11),var(--mce-bg-btn))}" +
		".mce-pg-card:hover{transform:translateY(-1px)}" +
		".mce-pg-card-h{display:flex;align-items:center;gap:6px;min-width:0}" +
		".mce-pg-ico{flex:none;width:26px;height:26px;border:1px solid var(--mce-border);border-radius:6px;background-color:rgba(0,0,0,.24);background-image:url('" + MB_CE_PG_ICONS + "');background-size:400% 200%;background-repeat:no-repeat;color:transparent;font-size:0;overflow:hidden}" +
		".mce-pg-ico-books{background-position:0 0}.mce-pg-ico-mirror{background-position:33.333% 0}.mce-pg-ico-weapons{background-position:66.666% 0}.mce-pg-ico-system{background-position:100% 0}.mce-pg-ico-economy{background-position:0 100%}.mce-pg-ico-hypno{background-position:33.333% 100%}.mce-pg-ico-new{background-position:66.666% 100%}" +
		".mce-pg-name{flex:1;min-width:0;font-size:13px;font-weight:800;color:var(--mce-txt-strong);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}" +
		".mce-pg-fav{flex:none;width:24px;height:24px;padding:0;border:1px solid transparent;border-radius:6px;background:transparent;color:var(--mce-muted);cursor:pointer;font-size:14px;line-height:1}" +
		".mce-pg-fav:hover{color:var(--mce-accent);border-color:var(--mce-border)}.mce-pg-fav:active{transform:scale(.94)}" +
		".mce-pg-sw{flex:none;min-width:34px;height:22px;padding:0 6px;border:1px solid var(--mce-border);border-radius:999px;background:rgba(0,0,0,.28);color:var(--mce-txt);font-size:10px;font-weight:700;cursor:pointer;font-family:inherit}" +
		".mce-pg-sw.on{background:var(--mce-accent);border-color:var(--mce-accent);color:var(--mce-txt-on-accent);box-shadow:0 0 12px -4px var(--mce-accent)}" +
		".mce-pg-sw:hover{filter:brightness(1.12)}.mce-pg-sw:active{transform:scale(.95)}" +
		".mce-pg-desc{font-size:11px;line-height:1.55;color:var(--mce-txt);opacity:.82;margin:6px 0 5px;min-height:34px}" +
		".mce-pg-tags{display:flex;flex-wrap:wrap;gap:4px}" +
		".mce-pg-tag{font-size:9px;line-height:1;padding:3px 5px;border-radius:4px;color:var(--mce-accent);border:1px solid rgba(212,175,55,.28);background:rgba(212,175,55,.06);white-space:nowrap}" +
		".mce-pg-subwrap{margin-top:6px;border-top:1px dashed var(--mce-border);padding-top:5px}" +
		".mce-pg-subtog{width:100%;text-align:left;border:1px solid var(--mce-border);border-radius:5px;background:rgba(0,0,0,.18);color:var(--mce-txt);font-size:10px;padding:4px 6px;cursor:pointer;font-family:inherit}" +
		".mce-pg-subs[data-collapsed='1']{display:none}.mce-pg-subs{margin-top:4px;border:1px solid var(--mce-border);border-radius:5px;overflow:hidden}" +
		".mce-pg-subrow{display:flex;align-items:center;gap:6px;justify-content:space-between;padding:4px 6px;border-bottom:1px solid rgba(255,255,255,.05);background:rgba(0,0,0,.12)}" +
		".mce-pg-subrow:last-child{border-bottom:0}" +
		".mce-pg-subname{font-size:10px;color:var(--mce-txt);min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}" +
		".mce-pg-entry{display:flex;align-items:center;gap:10px;justify-content:space-between;flex-wrap:wrap;padding:9px 10px;border:1px solid var(--mce-border);border-radius:var(--mce-radius);background:linear-gradient(120deg,rgba(212,175,55,.10),rgba(0,0,0,.12));margin:2px 0}" +
		".mce-pg-entry-l{display:flex;align-items:center;gap:8px;min-width:0;flex:1 1 100%}" +
		".mce-pg-entry-t{flex:1 1 auto;min-width:0}" +
		".mce-pg-entry-ico{flex:none;width:34px;height:34px;display:flex;align-items:center;justify-content:center;border:1px solid var(--mce-accent);border-radius:8px;color:var(--mce-accent);font-weight:900;background:rgba(0,0,0,.24)}" +
		".mce-pg-entry-name{font-size:14px;font-weight:900;color:var(--mce-txt-strong)}" +
		".mce-pg-entry-sub{font-size:10px;line-height:1.5;color:var(--mce-txt);opacity:.8;margin-top:2px}" +
		".mce-pg-entry-r{display:flex;align-items:center;gap:6px;flex-wrap:wrap;flex:1 1 100%;justify-content:space-between}" +
		"@media (max-width:560px){.mce-pg-grid{grid-template-columns:1fr}.mce-pg-hero{min-height:112px;padding:10px}.mce-pg-hero-mark{width:48px;height:48px;font-size:24px}.mce-pg-title{font-size:18px}.mce-pg-desc{min-height:0}.mce-pg-toolbar .mce-pg-search{flex-basis:100%}}";
